// src/node/file.js
import fs from "fs/promises";
import path from "path";
async function mkdir(path2) {
  return fs.mkdir(path2, { recursive: true });
}
async function copyFile(from, to) {
  const dir = path.dirname(to);
  await mkdir(dir);
  await fs.copyFile(from, to);
}
export {
  copyFile,
  mkdir
};
